// (AIP-164) when the price_rule has a delete_time, so Get still
// returns it and Undelete restores it.
func (s *PricingServiceServer) DeletePriceRule(ctx context.Context, req *pricingpbv1.DeletePriceRuleRequest) (*emptypb.Empty, error) {
	err := s.opts.Run(ctx, "PricingService", "DeletePriceRule", func(ctx context.Context) error {
		name := req.GetName()
		if err := servicex.CheckName("name", name, false, pricingServicePriceRuleCollections...); err != nil {
			return err
		}
		var existing *pricingpbv1.PriceRule
		if req.GetEtag() != "" || req.GetValidateOnly() {
			var err error
			existing, err = s.repos.PriceRules.Get(ctx, name)
			if err != nil {
				return servicex.NotFoundAs(err, pricingServicePriceRuleType, name)
			}
			if err := servicex.CheckEtag(pricingServicePriceRuleType, name, req.GetEtag(), existing.GetEtag()); err != nil {
				return err
			}
		}
		_ = existing
		if err := s.hooks.BeforeDeletePriceRule(ctx, name, false); err != nil {
			return err
		}
		if req.GetValidateOnly() {
			return nil
		}
		err := s.repos.PriceRules.Delete(ctx, name)
		if err != nil {
			return servicex.NotFoundAs(err, pricingServicePriceRuleType, name)
		}
		return s.hooks.AfterDeletePriceRule(ctx, name)
	})
	if err != nil {
		return nil, err
	}
	return &emptypb.Empty{}, nil
}
